def asignar_codigos_existentes(apps, schema_editor):
    User = apps.get_model('users', 'User')
    existentes = set(User.objects.exclude(codigo_unico=None).values_list('codigo_unico', flat=True))
    for user in User.objects.filter(codigo_unico=None):
        while True:
            codigo = f'{random.randint(0, 999999):06d}'
            if codigo not in existentes:
                existentes.add(codigo)
                break
        user.codigo_unico = codigo
        user.save(update_fields=['codigo_unico'])


